-- Local development seed data only. Never run against a production
-- project. See docs/DATABASE.md "Local development".

on conflict (slug) do nothing;

-- 44 possen.com fabrics added to Atelier Demo's Suits/Jackets catalogue.
-- Images: shared nebelspiegel.com catalogue photography (same CDN the
-- founder's own template already uses -- see paon-template.html route.ts's
-- usesSharedCataloguePhotography / suitOrJacketFromImageId, which buckets
-- by the 4-digit id in the image path: <8000 = Suits, >=8000 = Jackets.
on conflict (retailer_id, slug) do nothing;

on conflict (product_id, sku) do nothing;
-- Founder's original full catalogue (all 9 categories), restored from
-- www.nebelspiegel.com/paon.html after concurrent local `supabase db reset`
-- calls wiped the live (never-seeded) dev data. Additive to the 44 possen
-- fabrics already in this file -- category is embedded in `name` via the
-- same keyword/id-range heuristic apps/customer/app/r/[slug]/route.ts uses,
-- stored as a leading tag so it doesn't require a schema change; route.ts's
-- own canonicalCategoryFor() already re-derives the same category from the
-- name/image at request time, so this is redundant-but-harmless documentation.
on conflict (retailer_id, slug) do nothing;

on conflict (product_id, sku) do nothing;

-- Restore the retailer's own corner-radius setting: brand_theme's column
-- default is "soft" (1.25rem), which a plain `supabase db reset --local`
-- silently reasserts for any retailer whose theme customization only ever
-- lived in the running dev DB rather than this seed file (exactly what
-- happened here). `enforce_retailer_staff_editable_columns()` blocks a
-- plain UPDATE on brand_theme from the postgres/session role -- it only
-- allows service_role, is_platform_staff(), or a role-switched session,
-- so `set local role service_role` scopes the bypass to just this one
-- statement rather than weakening the trigger itself.
set local role service_role;
update public.retailers
  set brand_theme = jsonb_set(brand_theme, '{cornerStyle}', '"architectural"')
  where slug = 'atelier-demo';
reset role;
